@namespace sv_60b9c71ea6654ec688251eb9c2aef38f.Components.Pages.Board

<div class="task-card">
    <h4 class="task-title">@Task.Title</h4>
    <p class="task-assignee">@Task.Assignee</p>
    <span class="priority-badge priority-@Task.Priority.ToLowerInvariant()">@Task.Priority</span>
    <span class="task-due-date">@Task.DueDate.ToString("MMM dd")</span>
    <div class="task-actions">
        @if (CanMoveLeft)
        {
            <button class="btn-move" @onclick="OnMoveLeft">Move Left</button>
        }
        @if (CanMoveRight)
        {
            <button class="btn-move" @onclick="OnMoveRight">Move Right</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public TaskItem Task { get; set; } = default!;
    [Parameter] public bool CanMoveLeft { get; set; }
    [Parameter] public bool CanMoveRight { get; set; }
    [Parameter] public EventCallback OnMoveLeft { get; set; }
    [Parameter] public EventCallback OnMoveRight { get; set; }
}

@namespace sv_60b9c71ea6654ec688251eb9c2aef38f.Components.Pages.Board

<div class="add-task-form">
    <input type="text" placeholder="Title" @bind="title" />
    <input type="text" placeholder="Assignee" @bind="assignee" />
    <select @bind="priority">
        <option value="High">High</option>
        <option value="Medium">Medium</option>
        <option value="Low">Low</option>
    </select>
    <input type="date" @bind="dueDate" />
    <div class="form-actions">
        <button class="btn-save" @onclick="Save" disabled="@isSaving">Save</button>
        <button class="btn-cancel" @onclick="Cancel">Cancel</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string Status { get; set; } = default!;
    [Parameter] public EventCallback<TaskItem> OnTaskCreated { get; set; }
    [Parameter] public EventCallback OnCancel { get; set; }

    [Inject] private ITaskService TaskService { get; set; } = default!;

    private string title = string.Empty;
    private string assignee = string.Empty;
    private string priority = "Medium";
    private DateTime dueDate = DateTime.Today.AddDays(7);
    private bool isSaving;

    private async Task Save()
    {
        if (string.IsNullOrWhiteSpace(title)) return;

        isSaving = true;
        try
        {
            var task = await TaskService.CreateTaskAsync(title, assignee, priority, dueDate);
            await OnTaskCreated.InvokeAsync(task);
        }
        finally
        {
            isSaving = false;
        }
    }

    private async Task Cancel()
    {
        await OnCancel.InvokeAsync();
    }
}

@namespace sv_60b9c71ea6654ec688251eb9c2aef38f.Components.Pages.Board

<div class="kanban-column">
    <div class="column-header">
        <h3>@Title (@Tasks.Count)</h3>
    </div>
    <div class="column-body">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      CanMoveLeft="CanMoveLeft"
                      CanMoveRight="CanMoveRight"
                      OnMoveLeft="() => MoveLeft(task)"
                      OnMoveRight="() => MoveRight(task)" />
        }
    </div>
    <div class="column-footer">
        @if (showForm)
        {
            <AddTaskForm Status="@Status"
                         OnTaskCreated="HandleTaskCreated"
                         OnCancel="() => showForm = false" />
        }
        else
        {
            <button class="btn-add-task" @onclick="() => showForm = true">Add Task</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string Title { get; set; } = default!;
    [Parameter, EditorRequired] public string Status { get; set; } = default!;
    [Parameter] public List<TaskItem> Tasks { get; set; } = new();
    [Parameter] public bool CanMoveLeft { get; set; }
    [Parameter] public bool CanMoveRight { get; set; }
    [Parameter] public EventCallback<TaskItem> OnMoveLeft { get; set; }
    [Parameter] public EventCallback<TaskItem> OnMoveRight { get; set; }
    [Parameter] public EventCallback<TaskItem> OnTaskCreated { get; set; }

    private bool showForm;

    private async Task MoveLeft(TaskItem task)
    {
        await OnMoveLeft.InvokeAsync(task);
    }

    private async Task MoveRight(TaskItem task)
    {
        await OnMoveRight.InvokeAsync(task);
    }

    private async Task HandleTaskCreated(TaskItem task)
    {
        showForm = false;
        await OnTaskCreated.InvokeAsync(task);
    }
}

@namespace sv_60b9c71ea6654ec688251eb9c2aef38f.Components.Pages.Board

<div class="board-stats-bar">
    <span class="stat">Total: @Tasks.Count</span>
    <span class="stat">To Do: @Tasks.Count(t => t.Status == "To Do")</span>
    <span class="stat">In Progress: @Tasks.Count(t => t.Status == "In Progress")</span>
    <span class="stat">Done: @Tasks.Count(t => t.Status == "Done")</span>
    <span class="stat stat-overdue">Overdue: @Tasks.Count(t => t.DueDate < DateTime.Today)</span>
</div>

@code {
    [Parameter] public List<TaskItem> Tasks { get; set; } = new();
}

@namespace sv_60b9c71ea6654ec688251eb9c2aef38f.Components.Pages.Board

<div class="board-search-bar">
    <input type="text" placeholder="Search tasks by title..." value="@SearchTerm"
           @oninput="HandleInput" />
</div>

@code {
    [Parameter] public string SearchTerm { get; set; } = string.Empty;
    [Parameter] public EventCallback<string> SearchTermChanged { get; set; }

    private async Task HandleInput(ChangeEventArgs e)
    {
        var value = e.Value?.ToString() ?? string.Empty;
        await SearchTermChanged.InvokeAsync(value);
    }
}

@page "/board"
@namespace sv_60b9c71ea6654ec688251eb9c2aef38f.Components.Pages.Board
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

@if (isLoading)
{
    <p class="board-loading">Loading tasks...</p>
}
else if (errorMessage is not null)
{
    <p class="board-error">Error: @errorMessage</p>
}
else
{
    <BoardStatsBar Tasks="allTasks" />
    <BoardSearchBar SearchTerm="@searchTerm" SearchTermChanged="HandleSearchChanged" />

    <div class="kanban-board">
        <KanbanColumn Title="To Do" Status="To Do"
                      Tasks="GetFilteredTasks("To Do")"
                      CanMoveLeft="false" CanMoveRight="true"
                      OnMoveRight="task => MoveTask(task, "In Progress")"
                      OnTaskCreated="HandleTaskCreated" />

        <KanbanColumn Title="In Progress" Status="In Progress"
                      Tasks="GetFilteredTasks("In Progress")"
                      CanMoveLeft="true" CanMoveRight="true"
                      OnMoveLeft="task => MoveTask(task, "To Do")"
                      OnMoveRight="task => MoveTask(task, "Done")"
                      OnTaskCreated="HandleTaskCreated" />

        <KanbanColumn Title="Done" Status="Done"
                      Tasks="GetFilteredTasks("Done")"
                      CanMoveLeft="true" CanMoveRight="false"
                      OnMoveLeft="task => MoveTask(task, "In Progress")"
                      OnTaskCreated="HandleTaskCreated" />
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private string searchTerm = string.Empty;
    private bool isLoading = true;
    private string? errorMessage;

    protected override async Task OnInitializedAsync()
    {
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private List<TaskItem> GetFilteredTasks(string status)
    {
        var tasks = allTasks.Where(t => t.Status == status);
        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            tasks = tasks.Where(t => t.Title.Contains(searchTerm, StringComparison.OrdinalIgnoreCase));
        }
        return tasks.ToList();
    }

    private void HandleSearchChanged(string value)
    {
        searchTerm = value;
    }

    private async Task MoveTask(TaskItem task, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            var index = allTasks.FindIndex(t => t.Id == task.Id);
            if (index >= 0)
            {
                allTasks[index] = task with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
    }

    private void HandleTaskCreated(TaskItem task)
    {
        allTasks.Add(task);
    }
}

